response:
{
  "core_insight": "递归遍历不是“魔法深入”，而是每次调用把一个带返回地址的栈帧压入调用栈，子树处理完再弹出。",
  "render_medium": "svg",
  "render_medium_reason": "主视觉是树节点、父子连线和矩形栈帧的几何排布，SVG 便于按命名元素直接变换和着色。",
  "state_model": [
    {"name": "traversal", "type": "string", "range": "\"preorder\"|\"inorder\"|\"postorder\"", "init": "\"preorder\""},
    {"name": "step", "type": "int", "range": "0..maxSteps(traversal)", "init": "1"},
    {"name": "playing", "type": "bool", "range": "false|true", "init": "false"},
    {"name": "speed", "type": "float", "range": "0.5..2.0", "init": "1.0"}
  ],
  "interactions": [
    {"trigger": "select#traversal change", "effect": "traversal = value; step = 1; playing = false; 重新生成遍历事件序列并渲染"},
    {"trigger": "button#step-forward click", "effect": "if step < maxSteps then step++"},
    {"trigger": "button#step-back click", "effect": "if step > 0 then step--"},
    {"trigger": "button#play-pause click", "effect": "playing = !playing; 播放时按 speed 自动 step++"},
    {"trigger": "range#speed input", "effect": "speed = parseFloat(value); 调整自动步进间隔"}
  ],
  "update": "update() 根据 traversal 预计算（节点访问/左递归/右递归/弹栈）事件序列，按 step 截取：设置树节点 fill（未访问/当前/已访问）、高亮当前节点到父节点的边、在右侧栈区自上而下排列当前栈帧并显示“函数名(节点)”与返回位置。",
  "initial_paint": "preorder 第 1 步：根节点高亮为“当前访问”，根到左子的边预亮，右侧调用栈顶部已压入一个栈帧“preorder(A) — 待访问 A / 递归左子”，不是空舞台。"
}
